def distance(point1: Any, point2: Any) -> object {
    return (
        (
            ((point1[0] - point2[0]) ** 2)
            + ((point1[1] - point2[1]) ** 2)
            + ((point1[2] - point2[2]) ** 2)
        )
        ** 0.5
    );
}

